using System;

namespace Astrea;

public abstract class EndOfTurnOmenData : OmenData
{
	protected Action omenCheckActivationAction;

	public override void Initialize(OmenInstance omenInstance)
	{
		omenCheckActivationAction = GetOmenCheckActivationAction(omenInstance);
		ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.EndOfTurnOmenCheckActivateActions.Add(omenCheckActivationAction);
	}

	protected virtual Action GetOmenCheckActivationAction(OmenInstance omenInstance)
	{
		return delegate
		{
			ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.EndOfTurnOmenActions.Add(GetOmenAction(omenInstance));
		};
	}

	public abstract Action GetOmenAction(OmenInstance omenInstance);

	public override void OmenRemoved()
	{
		ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.EndOfTurnOmenCheckActivateActions.Remove(omenCheckActivationAction);
	}

	public string GetEndOfPlayerTurnLocalizedDescription()
	{
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedAtTheEndOfYourTurn();
	}
}
